        updateTextStyle: {
          range: r,
          textStyle: {
            foregroundColor: { color: { rgbColor: colors.gold } },
            fontSize: { magnitude: 10, unit: 'PT' }
          },
          fields: 'foregroundColor,fontSize'
        }
      });
      requests.push({
