      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'START',
            lineSpacing: 100,
            spaceAbove: { magnitude: 24, unit: 'PT' },
            spaceBelow: { magnitude: 0, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceAbove,spaceBelow'
        }
      });
      break;

    case 'execTitle':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 22, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.navy } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 700 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'START',
            lineSpacing: 100,
            spaceBelow: { magnitude: 4, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceBelow'
        }
      });
      break;

    case 'sectionTitle':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 18, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.darkBlue } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 600 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'START',
            lineSpacing: 100,
            spaceBelow: { magnitude: 4, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceBelow'
        }
      });
      break;

    case 'subheading':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 12, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.darkBlue } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 600 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: {
            alignment: 'START',
            lineSpacing: 100,
            spaceAbove: { magnitude: 18, unit: 'PT' },
            spaceBelow: { magnitude: 8, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceAbove,spaceBelow'
        }
      });
