    case 'footerText':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            fontSize: { magnitude: 10, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.lightGray } },
            weightedFontFamily: { fontFamily: 'Open Sans', weight: 400 }
          },
          fields: 'fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'CENTER',
            lineSpacing: 100,
            spaceAbove: { magnitude: 20, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceAbove'
        }
      });
      break;
  }
}

return [{ json: { docId, requests } }];
